  if(cb.checked) data[cb.id] = true;
});
document.querySelectorAll('textarea').forEach(function(ta) {
  if(ta.value.trim()) data[ta.id] = ta.value;
});
copy(JSON.stringify(data, null, 2));
alert("已複製到剪貼簿！貼給我！");

